const aiResponse = items[0].json.message.content;
const platformName = $node["Webhook Trigger"].json.body.platformName;
const entityType = $node["Webhook Trigger"].json.body.entityType;

try {
  // AI response'u JSON olarak parse et
  const mappingResult = JSON.parse(aiResponse);

  // Built-in transform fonksiyonları
  const builtInTransforms = {
    'toBoolean': 'value => value === true || value === "true" || value === 1 || value === "1" || value === "yes"',
    'toString': 'value => String(value || "")',
    'toNumber': 'value => Number(value) || 0',
    'toDecimal': 'value => parseFloat(value) || 0',
    'toDate': 'value => new Date(value).toISOString()',
    'toLowerCase': 'value => String(value).toLowerCase()',
    'toUpperCase': 'value => String(value).toUpperCase()',
    'parsePrice': 'value => parseFloat(String(value).replace(/[^0-9.]/g, "")) || 0',
    'formatDate': 'value => new Date(value).toISOString().split("T")[0]',
    'extractId': 'value => typeof value === "object" ? value.id : value',
    'arrayToString': 'value => Array.isArray(value) ? value.join(", ") : value',
    'firstImageUrl': 'value => Array.isArray(value) ? value[0] : value'
  };

  // Transform fonksiyonlarını birleştir
  const allTransforms = {
    ...builtInTransforms,
    ...(mappingResult.transformFunctions || {})
  };

  // Mapping'leri zenginleştir
  const enhancedMappings = (mappingResult.mappings || []).map(mapping => {
    // Confidence değeri ekle
    if (!mapping.confidence) {
      mapping.confidence = 0.7; // Default confidence
    }

    // Required field kontrolü
    const requiredFields = {
      product: ['Name', 'Sku', 'Price'],
      category: ['Name'],
      order: ['OrderTotal']
    };

    if (requiredFields[entityType] && requiredFields[entityType].includes(mapping.targetField)) {
      mapping.required = true;
    }

    return mapping;
  });

  // Validation rules
  const validationRules = {
    product: {
      'Name': { required: true, maxLength: 400 },
      'Sku': { required: true, maxLength: 400 },
      'Price': { required: true, min: 0, type: 'decimal' },
      'StockQuantity': { required: false, min: 0, type: 'integer' }
    },
    category: {
      'Name': { required: true, maxLength: 400 },
      'DisplayOrder': { required: false, min: 0, type: 'integer' }
    },
    order: {
      'OrderTotal': { required: true, min: 0, type: 'decimal' },
      'OrderNumber': { required: false, maxLength: 100 }
    }
  };

  return [{
    json: {
      platformName,
      entityType,
      mappings: enhancedMappings,
      transformFunctions: allTransforms,
      validationRules: validationRules[entityType] || {},
      aiGenerated: true,
      averageConfidence: enhancedMappings.reduce((sum, m) => sum + m.confidence, 0) / enhancedMappings.length,
      highConfidenceMappings: enhancedMappings.filter(m => m.confidence > 0.8).length,
      totalMappings: enhancedMappings.length
    }
  }];

} catch (error) {
  console.log('AI mapping parse failed, using manual mapping');

  // Fallback manual mapping
  const sampleData = $node["Fetch Sample Data"].json;
  const manualMappings = [];

  // Basit field matching
  const fieldMappings = {
    product: {
      'name|title|productName': 'Name',
      'sku|code|productCode': 'Sku',
      'price|cost|amount': 'Price',
      'description|desc': 'FullDescription',
      'stock|quantity': 'StockQuantity'
    },
    category: {
      'name|title|categoryName': 'Name',
      'description|desc': 'Description',
      'parent|parentId': 'ParentCategoryId'
    },
    order: {
      'total|amount|orderTotal': 'OrderTotal',
      'orderNumber|orderId': 'OrderNumber',
      'customer|customerId': 'CustomerId'
    }
  };

  const mappings = fieldMappings[entityType] || {};

  // Sample data field'larını tara
  for (const [key, value] of Object.entries(sampleData)) {
    for (const [patterns, targetField] of Object.entries(mappings)) {
      if (patterns.split('|').some(pattern => key.toLowerCase().includes(pattern))) {
        manualMappings.push({
          sourcePath: key,
          targetField,
          transformFunction: null,
          required: false,
          confidence: 0.6
        });
        break;
      }
    }
  }

  return [{
    json: {
      platformName,
      entityType,
      mappings: manualMappings,
      transformFunctions: {},
      validationRules: {},
      aiGenerated: false,
      fallbackUsed: true,
      error: error.message
    }
  }];
}

const mappingData = items[0].json;

// Test mapping ile sample data'yı dönüştürmeyi dene
const sampleData = $node["Fetch Sample Data"].json;
const testResults = [];
let successCount = 0;

for (const mapping of mappingData.mappings) {
  try {
    // Source path'den değeri al
    let value = sampleData;
    const pathParts = mapping.sourcePath.split('.');

    for (const part of pathParts) {
      if (part.includes('[0]')) {
        const fieldName = part.replace('[0]', '');
        value = value[fieldName] ? value[fieldName][0] : null;
      } else {
        value = value ? value[part] : null;
      }
    }

    // Transform fonksiyonunu uygula
    if (value !== null && mapping.transformFunction && mappingData.transformFunctions[mapping.transformFunction]) {
      const transformFn = eval(`(${mappingData.transformFunctions[mapping.transformFunction]})`);
      value = transformFn(value);
    }

    testResults.push({
      sourcePath: mapping.sourcePath,
      targetField: mapping.targetField,
      originalValue: sampleData[mapping.sourcePath],
      transformedValue: value,
      success: true,
      confidence: mapping.confidence
    });

    successCount++;
  } catch (error) {
    testResults.push({
      sourcePath: mapping.sourcePath,
      targetField: mapping.targetField,
      error: error.message,
      success: false,
      confidence: mapping.confidence
    });
  }
}

const testScore = successCount / mappingData.mappings.length;

return [{
  json: {
    ...mappingData,
    testResults,
    testScore,
    mappingQuality: testScore > 0.8 ? 'high' : testScore > 0.6 ? 'medium' : 'low',
    readyForProduction: testScore > 0.7 && mappingData.averageConfidence > 0.7
  }
}];
